class.description:
[ECSMainLoop] replaces [SceneTree] for projects built on the ECS: there are no nodes at all. It creates a viewport attached to the main window, a 2D canvas and a 3D scenario, hands them to its [ECSWorld] and calls [method ECSWorld.physics_update] and [method ECSWorld.update] every physics / render frame. Window input is forwarded to [method _input], and closing the window quits the loop.
To use it, set [code]application/run/main_loop_type[/code] to [code skip-lint]ECSMainLoop[/code] or to the name of a global class extending it:
[codeblock]
class_name Game
extends ECSMainLoop

var movers: ECSQuery

func _initialize():
    var world := get_world()
    var player := world.create_entity({&"LocalTransform2D": null, &"Velocity2D": {&"linear": Vector2(100, 0)}, &"Camera2D": null})
    world.set_sprite_texture(player, load("res://icon.svg"))
    movers = world.query([&"Velocity2D"])

func _input(event):
    if event.is_action_pressed(&"ui_cancel"):
        quit()
[/codeblock]
